-- spain.asturias
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'Spain''s damp Atlantic north-west is cider country, and wine is very much the exception — but one DOP survives inland at Cangas del Narcea, in the mountains of the south-west. Vines are worked on steep slate terraces above the Narcea and Ibias rivers, on a scale and a gradient that have far more in common with the Douro than with the rest of Asturias.', 'Atlantic and wet on the coast; the vineyards sit inland in sheltered river valleys where the rain eases and the summers are just warm enough to ripen.', 'Slate and schist, on terraces cut into very steep river slopes.', array['One DOP: Cangas, in the south-western mountains', 'Steep slate terraces above the Narcea', 'Cider country — wine is the exception', 'Albarín for white, Mencía for red']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'spain.asturias';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
