-- spain.baleares
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'Two DOs on Mallorca — Binissalem in the centre of the island and Pla i Llevant to the east — plus island-wide Vi de la Terra across the Balearics. The interest is almost entirely in the indigenous grapes: Manto Negro and Callet for red and Prensal for white, none of which are grown in quantity anywhere else, and most of the wine is drunk without ever leaving the islands.', 'Mediterranean and maritime — warm, dry summers with sea breezes taking the edge off the heat, and mild winters.', 'Clay and limestone over the islands'' calcareous bedrock.', array['Binissalem and Pla i Llevant, both on Mallorca', 'Manto Negro and Callet, grown almost nowhere else', 'Prensal for white', 'Most of it drunk on the islands']::text[], 'PUBLISHED'
