-- spain.madrid
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'DO Vinos de Madrid runs in four subzones around the capital, and spent most of its history supplying the city in bulk. It is now the setting for one of Spain''s more striking revivals: old bush-vine Garnacha on granite in the Gredos foothills around San Martín de Valdeiglesias, making pale, perfumed, high-altitude reds that have little to do with the region''s old reputation.', 'Continental and dry, with hot summers and cold winters. Altitude in the western subzone brings the cool nights the best reds depend on.', 'Granite and sand in the west around San Martín; clay and limestone in the subzones south and east of the city.', array['Four subzones: Arganda, Navalcarnero, San Martín and El Molar', 'Old-vine Garnacha on granite in the Gredos foothills', 'Albillo Real in San Martín, Malvar elsewhere', 'Long a bulk supplier to the capital']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'spain.madrid';
