-- spain.pais-vasco
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'The Basque Country makes two quite unrelated wines. On the coast, three Txakoli DOs — Getaria, Bizkaia and Araba — produce sharp, low-alcohol, faintly spritzy white from Hondarrabi Zuri, poured from a height and drunk within the year. Inland and south, across the Sierra de Cantabria, Rioja Alavesa lies within the Basque Country too, and makes Tempranillo in a completely different register.', 'Wet and Atlantic on the coast, where vines are trained high on pergolas to catch wind and light; sheltered and markedly drier in Rioja Alavesa behind the mountains.', 'Marl and sandstone near the coast; calcareous clay over limestone in Rioja Alavesa.', array['Three Txakoli DOs: Getaria, Bizkaia and Araba', 'Hondarrabi Zuri — sharp, low in alcohol, faintly spritzy', 'Rioja Alavesa also lies in the Basque Country', 'Txakoli is poured from a height to open it up']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'spain.pais-vasco';
